import axios from "axios";
import MaterialTable from "material-table";
import React, { Component } from "react";

import { connect } from "react-redux";
import { Spinner } from "reactstrap";
import { tokenConfig } from "../../actions/authActions";
import store from "../../store";
import Typography from "@material-ui/core/Typography";
import Breadcrumbs from "@material-ui/core/Breadcrumbs";
import Link from "@material-ui/core/Link";
import Card from "@material-ui/core/Card";
import { changePage } from "../../actions/pageActions";
import Checkbox from "@material-ui/core/Checkbox";
import InfoIcon from "@material-ui/icons/Info";
import { Button } from "@material-ui/core";

import CardContent from "@material-ui/core/CardContent";
class AccessConfiguration extends Component {
  state = {
    rowData1: [],
    tableLoaded: true,
    userAccessLoaded: true,
    userAccessName: "",
    userAccessId: 0,

    OA_1_E: false,
    OA_1_V: false,
    OA_2_E: false,
    OA_2_V: false,

    CBA: [], //arrays should contain the client ids

    COA_1_E: false,
    COA_1_V: false,
    COA_2_E: false,
    COA_2_V: false,
    COA_3_E: false,
    COA_3_V: false,

    PGOA_1_E: false,
    PGOA_1_V: false,
    PGOA_2_E: false,
    PGOA_2_V: false,
    PGOA_3_E: false,
    PGOA_3_V: false,

    IOA_1_E: false,
    IOA_1_V: false,
    IOA_2_E: false,
    IOA_2_V: false,
    IOA_3_E: false,
    IOA_3_V: false,

    POA_1_E: false,
    POA_1_V: false,
    POA_2_E: false,
    POA_2_V: false,
    POA_3_E: false,
    POA_3_V: false,
    POA_4_E: false,
    POA_4_V: false,
    POA_5_E: false,
    POA_5_V: false,
    POA_6_E: false,
    POA_6_V: false
  };

  componentDidMount() {
    this.retrieveClientsFromDb();
    this.retrieveUserAccessFromDb();
  }

  saveUserAccess = () => {
    axios
      .put(
        `/api/userAccessTypes/${this.state.userAccessId}`,
        { state: this.state, user: this.props.auth.user },
        tokenConfig(store.getState)
      )
      .then(res => {
        /*this.retrieveFromDb();
        this.setState(state => ({
          tableLoaded: true,
          rowData: state.rowData
        }));*/
      })
      .catch(err => console.log(err.data));

    /*this.setState({
      OA_1_E: !this.state.OA_1_E
    });*/
  };

  updateAccessState = e => {
    this.setState({
      [e.target.name]: !this.state[e.target.name]
    });
    console.log(this.state);
  };

  updateClientAccessState = e => {
    /*this.setState({
      [e.target.name]: !this.state[e.target.name]
    });*/
    var clientAccess = this.state.CBA;
    if (clientAccess.includes(e.target.id)) {
      clientAccess = clientAccess.filter((x, index) => {
        return x != e.target.id;
      });
    } else {
      clientAccess.push(e.target.id);
    }

    this.setState(state => ({
      CBA: clientAccess
    }));
    console.log(this.state.CBA);
  };

  retrieveUserAccessFromDb = () => {
    this.setState(state => ({
      userAccessLoaded: false
    }));
    axios
      .get(`/api/userAccessTypes/${this.props.page.page.objId}`)
      .then(res => {
        //console.log(res.data._id);
        if (res.data.access == null) {
          this.setState(state => ({
            userAccessLoaded: true,
            userAccessName: res.data.name,
            userAccessId: res.data._id
          }));
        } else {
          this.setState(state => ({
            userAccessLoaded: true,
            userAccessName: res.data.name,
            userAccessId: res.data._id,
            OA_1_E: res.data.access.OA_1_E,
            OA_1_V: res.data.access.OA_1_V,
            OA_2_E: res.data.access.OA_2_E,
            OA_2_V: res.data.access.OA_2_V
          }));
        }
      })
      .catch(err => console.log(err));
  };

  retrieveClientsFromDb = () => {
    this.setState(state => ({
      tableLoaded: false,
      rowData1: state.rowData1
    }));
    axios
      .get("/api/clients")
      .then(res => {
        var rowData1 = res.data.filter((x, index) => {
          return x.deletedAt == null;
        });
        rowData1 = rowData1.map((x, index) => {
          return {
            clientId: x._id,
            client: x.name,
            allow: (
              <Checkbox
                color="primary"
                id={x._id}
                onChange={this.updateClientAccessState}
              />
            )
          };
        });

        this.setState(state => ({
          tableLoaded: true,
          rowData1
        }));
      })
      .catch(err => console.log(err));
  };

  onPageChangeClick = (navType, page, objId) => {
    const pageDetail = {
      navType,
      page,
      objId
    };
    this.props.changePage(pageDetail);
  };

  render() {
    return (
      <div>
        {this.state.tableLoaded && this.state.userAccessLoaded ? (
          <div>
            <Card className="mb-2">
              <CardContent>
                <Breadcrumbs
                  style={{
                    display: "flex",
                    justifyContent: "center"
                  }}
                >
                  <Link
                    onClick={this.onPageChangeClick.bind(
                      this,
                      "OpsNav",
                      "AccessSetup",
                      0
                    )}
                  >
                    Create New Access
                  </Link>

                  <Typography color="textPrimary">
                    User Access Configuration
                  </Typography>
                </Breadcrumbs>
              </CardContent>
            </Card>

            <Card className="mb-2">
              <CardContent>
                <div
                  style={{
                    display: "flex",
                    justifyContent: "center"
                  }}
                >
                  <h4>{this.state.userAccessName} </h4>
                </div>
                <div
                  style={{
                    display: "flex",
                    justifyContent: "center"
                  }}
                >
                  <p>Access Setup ID: {this.state.userAccessId} </p>
                </div>
              </CardContent>
            </Card>

            <MaterialTable
              columns={[
                { title: "Description", field: "desc" },
                { title: "Add/Edit/Delete Access", field: "edit" },
                { title: "View Access", field: "view" }
              ]}
              options={{
                search: false,
                pageSize: 3,
                paging: false
              }}
              data={[
                {
                  desc: (
                    <div title="Allows access to Process Group objects created by self and users">
                      <InfoIcon />
                      User Access
                    </div>
                  ),
                  edit: (
                    <Checkbox
                      //checked={true}
                      color="primary"
                      name="OA_1_E"
                      checked={this.state.OA_1_E}
                      onChange={this.updateAccessState}
                    />
                  ),
                  view: (
                    <Checkbox
                      color="primary"
                      name="OA_1_V"
                      checked={this.state.OA_1_V}
                      onChange={this.updateAccessState}
                    />
                  )
                },
                {
                  desc: (
                    <div title="Allows access to Process Group object details created by self and users">
                      <InfoIcon />
                      Configuration History
                    </div>
                  ),
                  edit: (
                    <Checkbox
                      color="primary"
                      name="OA_2_E"
                      checked={this.state.OA_2_E}
                      onChange={this.updateAccessState}
                    />
                  ),
                  view: (
                    <Checkbox
                      color="primary"
                      name="OA_2_V"
                      checked={this.state.OA_2_V}
                      onChange={this.updateAccessState}
                    />
                  )
                }
              ]}
              title={<h5>Operations Access</h5>}
            />
            <div className="mb-2"> </div>
            <MaterialTable
              columns={[
                { title: "Client", field: "client" },
                { title: "Client Id", field: "clientId" },
                { title: "Allow Access", field: "allow" }
              ]}
              data={this.state.rowData1}
              title={
                <h5 title="This configuration determines user access to all the below configurations for each client in this table">
                  <InfoIcon /> Client Based Access
                </h5>
              }
            />
            <div className="mb-2"></div>
            <MaterialTable
              columns={[
                { title: "Description", field: "desc" },
                { title: "Add/Edit/Delete Access", field: "edit" },
                { title: "View Access", field: "view" }
              ]}
              options={{
                search: false,
                pageSize: 2,
                paging: false
              }}
              data={[
                {
                  desc: (
                    <div title="Allows access to Client objects created by self and users">
                      <InfoIcon />
                      Clients
                    </div>
                  ),
                  edit: (
                    <Checkbox
                      //checked={true}
                      color="primary"
                      name="COA_1_E"
                      checked={this.state.COA_1_E}
                      onChange={this.updateAccessState}
                    />
                  ),
                  view: (
                    <Checkbox
                      //checked={true}
                      color="primary"
                      name="COA_1_V"
                      checked={this.state.COA_1_V}
                      onChange={this.updateAccessState}
                    />
                  )
                },
                {
                  desc: (
                    <div title="Allows access to Client object details created by self and users">
                      <InfoIcon />
                      Client Details
                    </div>
                  ),
                  edit: (
                    <Checkbox
                      //checked={true}
                      color="primary"
                      name="COA_2_E"
                      checked={this.state.COA_2_E}
                      onChange={this.updateAccessState}
                    />
                  ),
                  view: (
                    <Checkbox
                      //checked={true}
                      color="primary"
                      name="COA_2_V"
                      checked={this.state.COA_2_V}
                      onChange={this.updateAccessState}
                    />
                  )
                },
                {
                  desc: (
                    <div title="Allows access to Client objects and Client details if it is created by self regardless of above Client object and Client detail configurations">
                      <InfoIcon />
                      Self Created Clients and Details
                    </div>
                  ),
                  edit: (
                    <Checkbox
                      //checked={true}
                      color="primary"
                      name="COA_3_E"
                      checked={this.state.COA_3_E}
                      onChange={this.updateAccessState}
                    />
                  ),
                  view: (
                    <Checkbox
                      //checked={true}
                      color="primary"
                      name="COA_3_V"
                      checked={this.state.COA_3_V}
                      onChange={this.updateAccessState}
                    />
                  )
                }
              ]}
              title={<h5>Client Object Access</h5>}
            />

            <div className="mb-2"> </div>

            <MaterialTable
              columns={[
                { title: "Description", field: "desc" },
                { title: "Add/Edit/Delete Access", field: "edit" },
                { title: "View Access", field: "view" }
              ]}
              options={{
                search: false,
                pageSize: 3,
                paging: false
              }}
              data={[
                {
                  desc: (
                    <div title="Allows access to Process Group objects created by self and users">
                      <InfoIcon />
                      Process Groups
                    </div>
                  ),
                  edit: (
                    <Checkbox
                      //checked={true}
                      color="primary"
                      name="PGOA_1_E"
                      checked={this.state.PGOA_1_E}
                      onChange={this.updateAccessState}
                    />
                  ),
                  view: (
                    <Checkbox
                      //checked={true}
                      color="primary"
                      name="PGOA_1_V"
                      checked={this.state.PGOA_1_V}
                      onChange={this.updateAccessState}
                    />
                  )
                },
                {
                  desc: (
                    <div title="Allows access to Process Group object details created by self and users">
                      <InfoIcon />
                      Process Group Details
                    </div>
                  ),
                  edit: (
                    <Checkbox
                      //checked={true}
                      color="primary"
                      name="PGOA_2_E"
                      checked={this.state.PGOA_2_E}
                      onChange={this.updateAccessState}
                    />
                  ),
                  view: (
                    <Checkbox
                      //checked={true}
                      color="primary"
                      name="PGOA_2_V"
                      checked={this.state.PGOA_2_V}
                      onChange={this.updateAccessState}
                    />
                  )
                },
                {
                  desc: (
                    <div title="Allows access to Process Group objects and Process Group details if it is created by self regardless of above Process Group object and Process Group detail configurations">
                      <InfoIcon />
                      Self Created Process Groups and Details
                    </div>
                  ),
                  edit: (
                    <Checkbox
                      //checked={true}
                      color="primary"
                      name="PGOA_3_E"
                      checked={this.state.PGOA_3_E}
                      onChange={this.updateAccessState}
                    />
                  ),
                  view: (
                    <Checkbox
                      //checked={true}
                      color="primary"
                      name="PGOA_3_V"
                      checked={this.state.PGOA_3_V}
                      onChange={this.updateAccessState}
                    />
                  )
                }
              ]}
              title={<h5>Process Group Object Access</h5>}
            />
            <div className="mb-2"></div>
            <MaterialTable
              columns={[
                { title: "Description", field: "desc" },
                { title: "Add/Edit/Delete Access", field: "edit" },
                { title: "View Access", field: "view" }
              ]}
              options={{
                search: false,
                pageSize: 3,
                paging: false
              }}
              data={[
                {
                  desc: (
                    <div title="Allows access to Item objects created by self and users">
                      <InfoIcon />
                      Items (Sourced Items)
                    </div>
                  ),
                  edit: (
                    <Checkbox
                      //checked={true}
                      color="primary"
                      name="IOA_1_E"
                      checked={this.state.IOA_1_E}
                      onChange={this.updateAccessState}
                    />
                  ),
                  view: (
                    <Checkbox
                      //checked={true}
                      color="primary"
                      name="IOA_1_V"
                      checked={this.state.IOA_1_V}
                      onChange={this.updateAccessState}
                    />
                  )
                },
                {
                  desc: (
                    <div title="Allows access to Item object details created by self and users">
                      <InfoIcon />
                      Items (Sourced Items) Details
                    </div>
                  ),
                  edit: (
                    <Checkbox
                      //checked={true}
                      color="primary"
                      name="IOA_2_E"
                      checked={this.state.IOA_2_E}
                      onChange={this.updateAccessState}
                    />
                  ),
                  view: (
                    <Checkbox
                      //checked={true}
                      color="primary"
                      name="IOA_2_V"
                      checked={this.state.IOA_1_V}
                      onChange={this.updateAccessState}
                    />
                  )
                },
                {
                  desc: (
                    <div title="Allows access to Item objects and Item details if it is created by self regardless of above Item object and Item detail configurations">
                      <InfoIcon />
                      Self Created Items (Sourced Items) and Details
                    </div>
                  ),
                  edit: (
                    <Checkbox
                      //checked={true}
                      color="primary"
                      name="IOA_3_E"
                      checked={this.state.IOA_3_E}
                      onChange={this.updateAccessState}
                    />
                  ),
                  view: (
                    <Checkbox
                      //checked={true}
                      color="primary"
                      name="IOA_3_V"
                      checked={this.state.IOA_3_V}
                      onChange={this.updateAccessState}
                    />
                  )
                }
              ]}
              title={<h5>Item Object Access</h5>}
            />
            <div className="mb-2"></div>
            <MaterialTable
              columns={[
                { title: "Description", field: "desc" },
                { title: "Add/Edit/Delete Access", field: "edit" },
                { title: "View Access", field: "view" }
              ]}
              options={{
                search: false,
                pageSize: 6,
                paging: false
              }}
              data={[
                {
                  desc: (
                    <div title="Allows access to Process objects and Process details if it is created by self regardless of above Process object and Process detail configurations">
                      <InfoIcon />
                      Self Created Processes
                    </div>
                  ),
                  edit: (
                    <Checkbox
                      //checked={true}
                      color="primary"
                      name="POA_1_E"
                      checked={this.state.POA_1_E}
                      onChange={this.updateAccessState}
                    />
                  ),
                  view: (
                    <Checkbox
                      //checked={true}
                      color="primary"
                      name="POA_1_V"
                      checked={this.state.POA_1_V}
                      onChange={this.updateAccessState}
                    />
                  )
                },
                {
                  desc: (
                    <div title="Allows access to Process: Machining objects created by self and users">
                      <InfoIcon />
                      Process: Machining
                    </div>
